// GetDeploymentSettingsWithResponse Retrieves the global settings for Platform Installer
//
// Fetches the global configuration settings based on the platform instance type and its supported form factors.
// Either form_factor or ssp_type must be provided, ssp_type parameter represents the platform instance type.
//
// For MEDIUM form factor:
//   - min_worker_count: 2
//   - max_worker_count: 2
//   - Note: Medium supports exactly 2 workers. Use Large form factor for 4+ workers
//
// For LARGE form factor:
//   - min_worker_count: 4
//   - max_worker_count: 13
//
// For EXTRA_LARGE form factor:
//   - min_worker_count: 8
//   - max_worker_count: 17
//   - Note: For high-scale deployments with all features
//
// For instance type parameter:
//   - AVI_OPERATIONS: AVI Operations deployment (form_factor is SMALL, worker_count: 2)
//   - ATP: Advanced Threat Protection (requires form_factor parameter)
//
// IP Pool Count Calculation:
// The API returns minimum IP pool counts (min_node_ip_pool_count and
// min_service_ip_pool_count) based on the form factor and worker count.
//
// For variable worker count form factors (Medium, Large, Extra-Large):
//   - worker_count parameter can override the default (must be within valid range)
//   - If not provided, min_worker_nodes from the form factor spec is used
//
// For fixed worker count instance types (LICENSING, AVI_OPERATIONS):
//   - worker_count parameter is ignored
//   - Always uses min_worker_nodes from the deployment spec
//
// Node IP Pool (all deployments): 2 + controller_count + worker_count
//
//	(1 for VIP + 1 for rolling upgrade + all node IPs)
//
// Service IP Pool (varies by deployment type):
//   - LICENSING/AVI_OPERATIONS: 3 IPs
//     (1 Contour + 1 kafka-external + 1 kafka broker, no scaleout)
//   - Medium: 5 IPs (1 Contour + 1 kafka-external + 3 kafka brokers hardcoded)
//   - Large/Extra-Large: 3 + ceil(worker_count/2)
//     (1 Contour + 1 kafka-external + 1 kafka broker + extra brokers for Kafka cluster)
//
// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /sspi/settings (the `GetDeploymentSettings` operationId).
func (c *ClientWithResponses) GetDeploymentSettingsWithResponse(ctx context.Context, params *GetDeploymentSettingsParams, reqEditors ...RequestEditorFn) (*GetDeploymentSettingsResponse, error) {
	rsp, err := c.GetDeploymentSettings(ctx, params, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseGetDeploymentSettingsResponse(rsp)
}

